'use client';
import {useEffect,useState} from 'react';
import {api,getAuthRole,getSuperAdminToken,saveAuthSession} from '@/lib/api';
import {useRouter} from 'next/navigation';
export default function AdminPage(){const router=useRouter();const[email,setEmail]=useState('');const[password,setPassword]=useState('');const[error,setError]=useState('');const[loading,setLoading]=useState(true);const[busy,setBusy]=useState(false);useEffect(()=>{if(getSuperAdminToken()&&getAuthRole()==='ADMIN')router.replace('/requests');else setLoading(false)},[router]);async function submit(e:React.FormEvent){e.preventDefault();setBusy(true);setError('');try{const r=await api.login(email,password);if(r.role!=='ADMIN')throw new Error('Akun ini adalah Super Admin. Gunakan halaman Super Admin.');saveAuthSession(r.token,r.email,r.role,r.user_id,r.user_name);router.replace('/requests')}catch(e){setError(e instanceof Error?e.message:'Login gagal')}finally{setBusy(false)}}if(loading)return <div className="loading">Memeriksa sesi…</div>;return <div className="auth-wrap"><div className="auth-card"><div className="eyebrow">TCC Finance • Admin Portal</div><h1>Login Admin</h1><p className="subtitle">Ajukan transaksi, event, dan kebutuhan brand. Persetujuan tetap berada di Super Admin.</p>{error&&<div className="alert">⚠ {error}</div>}<form className="form-grid" onSubmit={submit}><label>Email<input type="email" autoComplete="username" value={email} onChange={e=>setEmail(e.target.value)} placeholder="admin@contoh.com" required/></label><label>Password<input type="password" autoComplete="current-password" value={password} onChange={e=>setPassword(e.target.value)} placeholder="Password admin" required/></label><div className="wide"><button className="btn" disabled={busy}>{busy?'Memverifikasi…':'Login Admin'}</button></div></form><p className="helper">Belum punya akun? Minta Super Admin membuat akun melalui Manajemen Admin.</p></div></div>}
